package com.smartelectronicsupermarket.reporting.controller;

import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import com.smartelectronicsupermarket.common.web.ApiExceptionHandler;import com.smartelectronicsupermarket.reporting.dto.StoreDashboardResponse;import com.smartelectronicsupermarket.reporting.service.StoreDashboardService;import com.smartelectronicsupermarket.security.identity.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class StoreDashboardControllerTest{
 private final UUID store=UUID.randomUUID(),actor=UUID.randomUUID();private final Instant from=Instant.parse("2026-11-01T00:00:00Z"),to=Instant.parse("2026-12-01T00:00:00Z");private StoreDashboardService service;private MockMvc mvc;
 @BeforeEach void setup(){service=mock(StoreDashboardService.class);mvc=MockMvcBuilders.standaloneSetup(new StoreDashboardController(service)).setControllerAdvice(new ApiExceptionHandler()).build();}
 @Test void trustedActorAndStoreRangeReachService()throws Exception{var response=new StoreDashboardResponse(store,from,to,Instant.now(),BigDecimal.ZERO,0,0,0,0,0,null,"N/A_NO_ACCEPTANCE_EVENTS",List.of(),StoreDashboardResponse.effectiveness(null,BigDecimal.ZERO));when(service.load(store,from,to,actor)).thenReturn(response);mvc.perform(get("/api/v1/reports/store-summary").param("store_id",store.toString()).param("from",from.toString()).param("to",to.toString()).principal(new TrustedActorAuthenticationToken(new AuthenticatedActor(actor)))).andExpect(status().isOk()).andExpect(jsonPath("$.store_id").value(store.toString())).andExpect(jsonPath("$.ai_acceptance_rate").doesNotExist()).andExpect(jsonPath("$.ai_effectiveness.state").value("NO_ATTRIBUTED_SALES")).andExpect(jsonPath("$.ai_effectiveness.revenue_share_percent").doesNotExist());verify(service).load(store,from,to,actor);}
 @Test void missingPrincipalCannotReadReports()throws Exception{mvc.perform(get("/api/v1/reports/store-summary").param("store_id",store.toString()).param("from",from.toString()).param("to",to.toString())).andExpect(status().isForbidden());verifyNoInteractions(service);}
}
